import * as z from "zod";

export const schema = z
  .object({
    organizations: z
      .array(
        z
          .object({
            id: z.string().min(1, "ID is required.").meta({
              title: "ID",
              description:
                "A hidden stable identifier generated by the setup page.",
            }),
            slugs: z
              .array(
                z
                  .object({
                    isActive: z.boolean().default(true).meta({
                      title: "Is Active",
                      description:
                        "Whether this slug is active and should be used to access the organisation.",
                    }),
                    slug: z.string().min(1, "Slug is required.").meta({
                      title: "Slug",
                      description:
                        "A unique URL slug generated from the organisation name.",
                    }),
                  })
                  .meta({
                    title: "Slug",
                    description:
                      "A unique URL slug generated from the organisation name.",
                  }),
              )
              .default([])
              .meta({
                title: "Slugs",
                description:
                  "The list of slugs including historical ones that can be used to access the organisation.",
              }),
            name: z.string().min(1, "Name is required.").meta({
              title: "Name",
              description:
                "The name of the organisation, e.g. 'Grade 10 · Batch 2083', 'Science & Math Faculty'.",
            }),
            type: z.enum(["School", "Class", "Faculty", "Others"]).meta({
              title: "Type",
              description:
                "The type of organisation: School, Class, Faculty, or Others.",
            }),
            logo: z.string().optional().meta({
              title: "Logo",
              description:
                "An optional logo or image representing the organisation.",
            }),
          })
          .meta({
            title: "Organisation",
            description:
              "Metadata for an organisation. Detailed information like people and description are stored in a separate file named after its ID.",
          }),
      )
      .default([])
      .meta({
        title: "Organisations",
        description:
          "The list of organisations such as classes, faculties, and committees.",
      }),
  })
  .meta({
    title: "Organisations Configuration",
    description:
      "Configuration for the organisations page and its organisation entries.",
  });

export const buildSchema = schema
  .extend({
  })
  .partial();

export type TInput = z.input<typeof schema>;
export type TOutput = z.output<typeof schema>;
export type TModel = TOutput;

export const defaultValues: TInput = {
  organizations: [],
};
